const publishedCompanyRecords = companyRecords.filter((company) => company.slug !== "salesforce");

type WaveTwoJobDraft = Pick<Job, "id" | "companySlug" | "title" | "segment" | "location" | "workStyle" | "language" | "source" | "descriptionSummary" | "genbaTake" | "desiredProfile"> & {
  firstSeen?: string;
  lastChecked?: string;
  fit: string;
  thingsToKnow: string;
  marketValue: string;
  tenureAndPromotion?: string;
  priorCompanies?: string;
  nextCompanies?: string;
};

function makeWaveTwoJob(draft: WaveTwoJobDraft): Job {
  return {
    id: draft.id,
    companySlug: draft.companySlug,
    title: draft.title,
    segment: draft.segment,
    location: draft.location,
    workStyle: draft.workStyle,
    language: draft.language,
    firstSeen: draft.firstSeen ?? "2026-08-12",
    lastChecked: draft.lastChecked ?? "2026-08-13",
    source: draft.source,
    descriptionSummary: draft.descriptionSummary,
    genbaTake: draft.genbaTake,
    compensationReality: "日本の給与、OTE、equity、quotaは公式求人で確認できない。pay mix、ramp、accelerator、案件creditを選考で確認したい。",
    desiredProfile: draft.desiredProfile,
    careerInsights: {
      fit: draft.fit,
      thingsToKnow: draft.thingsToKnow,
      marketValue: draft.marketValue,
      tenureAndPromotion: draft.tenureAndPromotion ?? "日本teamの平均在籍年数、離職率、昇進速度を示す公式dataは確認できない。入社後のramp基準と昇進実例を面接で確認したい。",
      priorCompanies: draft.priorCompanies ?? "日本営業の出身企業を示す十分な公開sampleは未確認。求人要件に記載された業界・segment・sales motionとの隣接性から判断する必要がある。",
      nextCompanies: draft.nextCompanies ?? "退職後の転職先を示す十分な公開sampleは未確認。隣接カテゴリへの展開可能性は仮説であり、実績として語れるbuyer、deal size、技術領域で評価が変わる。",
    },
  };
}

